const input = $('Normalize Input').item.json;
const classification = $json.output || $json;

const knowledgeBase = [
  { id: 'KB-01', category: 'course_question', keywords: ['github', 'export', 'json', 'submit', 'folder'], question: 'How do I submit my n8n workflow JSON?', answer: 'Export your workflow from n8n via Menu -> Download, save the JSON file into the designated folder in your GitHub repository (e.g., midterm/ or labs/), and include both the GitHub URL and n8n workflow URL in your Canvas submission.' },
  { id: 'KB-02', category: 'course_question', keywords: ['workflow', 'name', 'initials', 'publish', 'activate'], question: 'How should I name workflows and should I publish them?', answer: 'Prefix all workflow names with your initials (e.g., "AA - Workflow Name") and leave workflows unpublished/inactive unless specifically instructed to test a schedule trigger.' },
  { id: 'KB-03', category: 'course_question', keywords: ['data table', 'column', 'map', 'insert', 'schema'], question: 'Why does my Data Table node fail with unknown column name?', answer: 'When using Map Automatically, every incoming JSON field name must match a Data Table column name character-for-character in lowercase with underscores.' },
  { id: 'KB-04', category: 'grade_inquiry', keywords: ['grade', 'score', 'points', 'rubric', 'graded'], question: 'When are labs and projects graded and how is partial credit awarded?', answer: 'Assignments are graded within 5 business days after the due date using the Canvas rubric. Partial credit is awarded for working components even if downstream nodes have minor issues.' },
  { id: 'KB-05', category: 'grade_inquiry', keywords: ['regrade', 'missing', 'zero', 'incorrect', 'review'], question: 'What if I believe my assignment was graded incorrectly?', answer: 'Reply directly in the Canvas submission comment box within 7 days of grade posting with your workflow URL and a brief note explaining which rubric item you would like re-reviewed.' },
  { id: 'KB-06', category: 'deadline_extension', keywords: ['late', 'extension', 'deadline', 'due', 'sick', 'emergency'], question: 'Can I request a deadline extension for a lab or project?', answer: 'Students may request a 48-hour grace extension before the assignment lock date by messaging the instructor with their current progress. Midterm and Final projects require documented emergencies after the due date.' },
  { id: 'KB-07', category: 'deadline_extension', keywords: ['locked', 'closed', 'past due', 'reopen'], question: 'Canvas says the assignment is locked. Can I still submit?', answer: 'Once the Canvas availability window locks, submissions close automatically. Contact the instructor via Canvas Inbox with your GitHub commit timestamp to request an unlock.' },
  { id: 'KB-08', category: 'technical_issue', keywords: ['openrouter', 'api key', 'credential', 'vibe', 'model'], question: 'How do I set up my OpenRouter API key in n8n?', answer: 'Retrieve your class OpenRouter key at vibe.edumacation.net/cis091 using the course password, then create an OpenRouter credential in n8n and select model deepseek/deepseek-v4.1-flash-1017.' },
  { id: 'KB-09', category: 'technical_issue', keywords: ['webhook', 'body', 'post', 'curl', 'undefined'], question: 'Why is my Webhook data coming through as undefined?', answer: 'n8n Webhook triggers nest incoming POST JSON payloads under the "body" property. Reference fields using {{ $json.body.message }} instead of {{ $json.message }}.' },
  { id: 'KB-10', category: 'technical_issue', keywords: ['wsl', 'bash', 'pi', 'terminal', 'n8n_api_key'], question: 'How do I connect pi in WSL2 to the n8n server?', answer: 'Export N8N_API_KEY in your WSL2 ~/.bashrc file, reload with source ~/.bashrc, and run pi --tools bash inside your project directory containing AGENTS.md.' },
  { id: 'KB-11', category: 'general_inquiry', keywords: ['office hours', 'tutoring', 'help', 'tasc', 'zoom'], question: 'When are office hours and tutoring available?', answer: 'Instructor Zoom office hours are held Tuesdays and Thursdays from 4:00 PM to 5:30 PM, and free peer tutoring is available through College of the Desert TASC Tutoring.' },
  { id: 'KB-12', category: 'general_inquiry', keywords: ['syllabus', 'software', 'cost', 'account'], question: 'Do I need to pay for n8n or OpenRouter for this course?', answer: 'No. Course-hosted n8n accounts and OpenRouter API keys are provided free of charge to enrolled CIS 91 students for the duration of the semester.' }
];

const queryText = `${input.subject} ${input.message}`.toLowerCase();
const scored = knowledgeBase.map(entry => {
  const keywordHits = entry.keywords.filter(kw => queryText.includes(kw)).length;
  const categoryBonus = entry.category === classification.category ? 1 : 0;
  return { ...entry, score: keywordHits * 2 + categoryBonus };
}).filter(e => e.score >= 2).sort((a, b) => b.score - a.score);

const topMatches = scored.slice(0, 2);
const matchedSummary = topMatches.length > 0
  ? topMatches.map(m => `[${m.id}] ${m.question} -> ${m.answer}`).join('\n')
  : 'NO_DIRECT_KB_MATCH';

return {
  json: {
    ...input,
    category: classification.category || 'general_inquiry',
    confidence: classification.confidence ?? 0.5,
    reasoning: classification.reasoning || '',
    matched_kb_ids: topMatches.length > 0 ? topMatches.map(m => m.id).join(', ') : 'None',
    matched_kb_text: matchedSummary
  }
};

parameters.text:
=You are a helpful, professional CIS 91 Course & IT Support assistant.
Draft a clear, polite email/chat reply to the student below.

Student Sender: {{ $json.sender }}
Subject: {{ $json.subject }}
Message: {{ $json.message }}
Detected Category: {{ $json.category }} (Confidence: {{ $json.confidence }})

Relevant Knowledge Base Entries:
{{ $json.matched_kb_text }}

Instructions:
1. Directly address the student's specific question using the Knowledge Base entries above when relevant.
2. If Relevant Knowledge Base Entries says "NO_DIRECT_KB_MATCH", politely state that the topic is outside the automated FAQ scope and provide clear escalation steps (contact the instructor via Canvas Inbox or attend Tue/Thu 4:00-5:30 PM office hours).
3. Keep the tone warm, concise, and professional, and include clear next steps.
4. Return ONLY the plain-text reply message (no JSON wrapper).

