const prev = $('Search Knowledge Base').item.json;
const replyText = ($json.text || $json.output || $json.response || '').trim();

return {
  json: {
    timestamp: prev.timestamp,
    sender: prev.sender,
    subject: prev.subject,
    original_message: prev.message,
    category: prev.category,
    confidence: prev.confidence,
    matched_kb: prev.matched_kb_ids,
    ai_response: replyText,
    delivery_status: replyText ? 'delivered_via_webhook' : 'failed_empty_reply'
  }
};
